// ─── PARSER Browserless — Lidl + Intermarché ────────────────────────────────
// Input : HTML rendu par Chromium via Browserless /content
// Le nœud HTTP avec responseFormat:text met le HTML dans $json.data

const FOOD_KEYWORDS = [
  'lait','yaourt','fromage','beurre','crème','oeuf','oeufs','feta','mozzarella',
  'camembert','emmental','comté','chèvre','ricotta','mascarpone',
  'poulet','boeuf','porc','veau','agneau','saumon','thon','crevette','cabillaud',
  'jambon','lardons','bacon','saucisse','merguez','chipolata','canard','steak',
  'tomate','carotte','courgette','oignon','salade','poireau','brocoli','poivron',
  'avocat','concombre','champignon','épinard','aubergine','haricot',
  'pomme','banane','orange','poire','fraise','raisin','melon','pêche','citron','ananas',
  'pâtes','riz','farine','pain','baguette','céréales','lentilles','quinoa','semoule',
  'huile','sauce tomate','moutarde','mayonnaise','ketchup','vinaigre',
  'eau','jus','café','thé','bière','vin','sirop',
  'pizza','surgelé','conserve','maïs','soupe','confiture','miel','chocolat',
  'escalope','nuggets','côte','filet',
];

const CATEGORY_MAP = [
  [['fruit','légume','carotte','poivron','salade','courgette','tomate','concombre','épinard','brocoli','oignon','ail','poireau','aubergine','champignon','avocat','banane','poire','pêche','fraise','cerise','raisin','melon','ananas','orange','citron','pomme de terre'], 'Fruits & Légumes'],
  [['viande','boucherie','poulet','boeuf','porc','veau','agneau','côte','steak','filet','canard','lapin','dinde','rôti','escalope','nuggets'], 'Viandes & Poissons'],
  [['poisson','saumon','thon','crevette','cabillaud','moule','huître','dorade','bar','truite','sardine'], 'Viandes & Poissons'],
  [['lait','yaourt','fromage','beurre','crème','laitier','oeuf','feta','emmental','camembert','chèvre','mozzarella','ricotta'], 'Produits Laitiers'],
  [['surgelé','congel','glace'], 'Surgelés'],
  [['pain','boulang','viennoiserie','brioche','baguette','croissant','madeleine'], 'Boulangerie'],
  [['bière','vin','eau','jus','boisson','soda','café','thé','sirop','cidre','champagne'], 'Boissons'],
  [['jambon','charcuterie','saucisson','lardons','bacon','rillette','pâté','chorizo','merguez'], 'Charcuterie'],
];

const CHAIN_HINTS = [
  ['lidl', 'Lidl'],
  ['intermarche', 'Intermarché'],
  ['intermarché', 'Intermarché'],
  ['carrefour', 'Carrefour'],
  ['auchan', 'Auchan'],
  ['leclerc', 'Leclerc'],
  ['super u', 'Super U'],
  ['monoprix', 'Monoprix'],
];

function guessCategory(text) {
  const lower = text.toLowerCase();
  for (const [keywords, cat] of CATEGORY_MAP) {
    if (keywords.some(k => lower.includes(k))) return cat;
  }
  return 'Épicerie';
}

function isFood(text) {
  const lower = text.toLowerCase();
  return FOOD_KEYWORDS.some(k => lower.includes(k)) ||
    CATEGORY_MAP.some(([kws]) => kws.some(k => lower.includes(k)));
}

function nextSunday() {
  const d = new Date();
  d.setDate(d.getDate() + (7 - d.getDay() || 7));
  return d.toISOString().split('T')[0];
}

function cleanName(name) {
  return name
    .replace(/\d+\s*(g|kg|ml|cl|l|litres?|pièces?|unités?|x\d+)/gi, '')
    .replace(/[\s]+/g, ' ')
    .trim();
}

function guessChain(html) {
  const lower = html.substring(0, 3000).toLowerCase();
  for (const [key, val] of CHAIN_HINTS) {
    if (lower.includes(key)) return val;
  }
  return 'Inconnu';
}

function stripHtml(html) {
  return html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&#\d+;/g, '')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

const deals = [];
const inputs = $input.all();

for (const input of inputs) {
  // Browserless /content avec responseFormat:text → $json.data
  const rawHtml = String(input.json.data || input.json.html || input.json.body || '');
  if (rawHtml.length < 200) continue;

  const chainName = guessChain(rawHtml);

  // ── 1. JSON-LD schema.org Product ──────────────────────────────────────────
  const jsonLdRegex = /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let ldMatch;
  let foundViaJsonLd = false;

  while ((ldMatch = jsonLdRegex.exec(rawHtml)) !== null) {
    try {
      const data = JSON.parse(ldMatch[1]);
      const items = Array.isArray(data) ? data : (data['@graph'] ? data['@graph'] : [data]);
      for (const item of items) {
        const type = Array.isArray(item['@type']) ? item['@type'][0] : item['@type'];
        if (!['Product', 'Offer'].includes(type)) continue;

        const name = cleanName(String(item.name || ''));
        if (name.length < 3 || !isFood(name)) continue;

        const offerObj = item.offers || item;
        const rawPrice = offerObj.price ?? offerObj.lowPrice ?? offerObj.minPrice ?? null;
        if (rawPrice === null) continue;
        const price = parseFloat(String(rawPrice).replace(',', '.'));
        if (isNaN(price) || price <= 0 || price > 300) continue;

        foundViaJsonLd = true;
        deals.push({
          item: name.charAt(0).toUpperCase() + name.slice(1).toLowerCase(),
          chain: chainName,
          brand: typeof item.brand?.name === 'string' ? item.brand.name : null,
          price_promo: Math.round(price * 100) / 100,
          price_normal: null,
          unit: null,
          valid_until: nextSunday(),
          region: 'national',
          category: guessCategory(name),
        });
      }
    } catch { /* JSON-LD invalide */ }
  }

  // ── 2. Fallback : regex prix ─────────────────────────────────────────────────
  if (!foundViaJsonLd) {
    const text = stripHtml(rawHtml);
    const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 2);

    for (const line of lines) {
      const priceMatches = [...line.matchAll(/(\d{1,3}[,.]\d{2})\s*€/g)];
      if (priceMatches.length === 0) continue;

      const firstPriceIdx = line.indexOf(priceMatches[0][0]);
      let name = line.substring(0, firstPriceIdx).replace(/[-–—:|]/g, ' ').trim();
      name = cleanName(name);
      if (name.length < 3 || name.length > 80) continue;
      if (!isFood(name + ' ' + line)) continue;

      const pricePromo = parseFloat(priceMatches[0][1].replace(',', '.'));
      const priceNormal = priceMatches.length > 1
        ? parseFloat(priceMatches[1][1].replace(',', '.'))
        : null;

      if (isNaN(pricePromo) || pricePromo <= 0 || pricePromo > 200) continue;

      const unitMatch = line.match(/(le\s+kg|la\s+pièce|\d+\s*g\b|\d+\s*kg\b|\d+\s*cl\b|\d+\s*l\b|\d+\s*ml\b)/i);

      deals.push({
        item: name.charAt(0).toUpperCase() + name.slice(1).toLowerCase(),
        chain: chainName,
        brand: null,
        price_promo: Math.round(pricePromo * 100) / 100,
        price_normal: priceNormal && priceNormal > pricePromo ? Math.round(priceNormal * 100) / 100 : null,
        unit: unitMatch ? unitMatch[0].trim() : null,
        valid_until: nextSunday(),
        region: 'national',
        category: guessCategory(name),
      });
    }
  }
}

// ── Dédoublonner ─────────────────────────────────────────────────────────────
const seen = new Map();
const deduped = [];
for (const d of deals) {
  const key = `${d.item.toLowerCase().slice(0, 25)}-${d.chain.toLowerCase()}`;
  const ex = seen.get(key);
  if (!ex || d.price_promo < ex.price_promo) {
    if (ex) deduped.splice(deduped.indexOf(ex), 1);
    seen.set(key, d);
    deduped.push(d);
  }
}

return [{ json: { deals: deduped, count: deduped.length, sources: ['lidl.fr', 'intermarche.com', 'carrefour.fr'] } }];
